import copy
import random
import sys
import time
from itertools import product

sys.path.insert(0, "/tmp/workspace")
from scheduler import schedule

fails = []


def check(cond, label):
    if cond:
        print(f"  ok   {label}")
    else:
        print(f"  FAIL {label}")
        fails.append(label)


def reference(graph):
    """Brute-force greedy: repeatedly take min ready node. Raises like the spec."""
    for node, deps in graph.items():
        for d in deps:
            if d not in graph:
                raise KeyError(d)
    emitted = set()
    order = []
    nodes = list(graph)
    while len(order) < len(nodes):
        ready = [n for n in nodes if n not in emitted and all(d in emitted for d in graph[n])]
        if not ready:
            raise ValueError("cycle")
        nxt = min(ready)
        emitted.add(nxt)
        order.append(nxt)
    return order


print("[1] public example + basic cases")
check(schedule({'b': ['a'], 'a': []}) == ['a', 'b'], "public example")
check(schedule({}) == [], "empty graph")
check(schedule({'a': []}) == ['a'], "single node")
check(schedule({'c': [], 'b': [], 'a': []}) == ['a', 'b', 'c'], "insertion order ignored")
check(schedule({'a': [], 'b': [], 'c': ['a', 'b']}) == ['a', 'b', 'c'], "diamond-ish")
check(schedule({3: [], 1: [], 2: [1, 3]}) == [1, 2, 3] or schedule({3: [], 1: [], 2: [1, 3]}) == [1, 3, 2],
      "integer nodes")
check(schedule({3: [], 1: [], 2: [1, 3]}) == [1, 3, 2], "integer lexicographic tie-break")
# greedy lexicographic: prefer 'a' now even though it unlocks nothing
g = {'b': [], 'a': ['b']}
check(schedule(g) == ['b', 'a'], "dependency forces order")
g = {'a': [], 'b': ['c'], 'c': []}
check(schedule(g) == ['a', 'c', 'b'], "smallest ready first even if it delays others")

print("[2] error handling")
for cyc in ({'a': ['a']}, {'a': ['b'], 'b': ['a']}, {'a': ['b'], 'b': ['c'], 'c': ['a']},
            {'a': [], 'b': ['c'], 'c': ['b']}):
    try:
        schedule(cyc)
        check(False, f"cycle {cyc} -> ValueError")
    except ValueError:
        check(True, f"cycle {cyc} -> ValueError")
    except Exception as e:  # noqa: BLE001
        check(False, f"cycle {cyc} raised {type(e).__name__}")

for bad in ({'a': ['z']}, {'a': ['b'], 'b': ['zz']}, {'a': ['a', 'missing']}):
    try:
        schedule(bad)
        check(False, f"missing dep {bad} -> KeyError")
    except KeyError as e:
        check(e.args[0] in ('z', 'zz', 'missing'), f"missing dep {bad} -> KeyError({e.args[0]!r})")
    except Exception as e:  # noqa: BLE001
        check(False, f"missing dep {bad} raised {type(e).__name__}")
# dep present only as a value of another entry is still absent as a node
try:
    schedule({'a': ['b'], 'c': ['b']})
    check(False, "value-only node -> KeyError")
except KeyError:
    check(True, "value-only node -> KeyError")

print("[3] no mutation of input")
cases = [
    {'b': ['a'], 'a': [], 'c': ['a', 'b']},
    {'x': [], 'y': ['x'], 'z': ['y']},
    {},
    {'a': ['b', 'b'], 'b': []},
]
for g in cases:
    snap = copy.deepcopy(g)
    reprs = {k: repr(v) for k, v in g.items()}
    schedule(g)
    check(g == snap and {k: repr(v) for k, v in g.items()} == reprs, f"unchanged {snap}")

# tuple deps and set deps also accepted / unmutated
g = {'a': ('b',), 'b': ()}
check(schedule(g) == ['b', 'a'] and g == {'a': ('b',), 'b': ()}, "tuple deps")
g = {'a': {'b'}, 'b': set()}
check(schedule(g) == ['b', 'a'], "set deps")

print("[4] duplicate dependencies")
check(schedule({'a': ['b', 'b'], 'b': []}) == ['b', 'a'], "duplicate dep")
check(schedule({'a': ['b', 'b'], 'b': [], 'c': []}) == ['b', 'c', 'a'], "duplicate dep + tie")

print("[5] randomized cross-check vs brute force")
random.seed(1234)
for trial in range(4000):
    n = random.randint(0, 7)
    names = [chr(ord('a') + i) for i in range(n)]
    g = {}
    for i, node in enumerate(names):
        # deps only from earlier-listed nodes -> guaranteed acyclic
        pool = names[:i]
        deps = [d for d in pool if random.random() < 0.35]
        if deps and random.random() < 0.15:
            deps.append(random.choice(deps))  # duplicate edge
        g[node] = deps
    random.shuffle(names)
    g = {k: g[k] for k in names}  # random insertion order
    snap = copy.deepcopy(g)
    got, want = schedule(g), reference(g)
    if got != want or g != snap:
        check(False, f"random trial {trial}: got {got}, want {want}, mutated={g != snap}")
        break
else:
    check(True, "4000 random DAGs match brute-force lexicographic order, no mutation")

# randomized graphs containing cycles: both must raise ValueError
for trial in range(2000):
    n = random.randint(1, 6)
    names = [chr(ord('a') + i) for i in range(n)]
    g = {node: [d for d in names if random.random() < 0.3] for node in names}
    if any(d not in g for node in g for d in g[node]):
        continue
    def raises(fn):
        try:
            fn(g)
            return False
        except ValueError:
            return True
        except KeyError:
            return None
    got = raises(schedule)
    want = raises(reference)
    if got is not False and got != want:  # schedule raised ValueError or KeyError inconsistently
        check(False, f"cycle trial {trial}: schedule={got}, reference={want}")
        break
    if got is False and len(names) > 0:
        # acyclic here; ensure equality
        if schedule(g) != reference(g):
            check(False, f"acyclic random trial {trial} mismatch")
            break
else:
    check(True, "2000 random cyclic graphs agree with reference")

print("[6] valid topological order on random DAGs (properties)")
random.seed(99)
for trial in range(500):
    n = random.randint(0, 30)
    g = {i: [] for i in range(n)}
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < 0.08:
                g[j].append(i)
    order = schedule(g)
    pos = {node: idx for idx, node in enumerate(order)}
    if sorted(order) != list(range(n)) or any(pos[d] >= pos[node] for node, deps in g.items() for d in deps):
        check(False, f"invalid topological order on trial {trial}")
        break
else:
    check(True, "500 random DAGs: valid permutation and all edges respected")

print("[7] insertion-order independence")
random.seed(7)
for trial in range(300):
    n = 9
    base = {i: [] for i in range(n)}
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < 0.3:
                base[j].append(i)
    keys = list(base)
    results = set()
    for _ in range(6):
        random.shuffle(keys)
        results.add(tuple(schedule({k: list(base[k]) for k in keys})))
    if len(results) != 1:
        check(False, f"insertion order changed result on trial {trial}: {results}")
        break
else:
    check(True, "300 shuffled graphs produce a single deterministic order")

print("[8] scale / no recursion limits")
N = 200_000
big = {i: [i - 1] for i in range(1, N)}
big[0] = []
t0 = time.perf_counter()
res = schedule(big)
dt = time.perf_counter() - t0
check(res == list(range(N)), f"chain of {N} nodes correct in {dt:.2f}s")

wide = {i: [] for i in range(N)}
wide['z'] = []
t0 = time.perf_counter()
res = schedule(wide)
dt = time.perf_counter() - t0
check(res[-1] == 'z' and res[:3] == [0, 1, 2], f"wide graph of {N + 1} nodes in {dt:.2f}s")

print()
if fails:
    print(f"FAILURES: {fails}")
    sys.exit(1)
print("ALL CHECKS PASSED")
